def order_total_cents(lines, tax_percent):
    """Total of an order in whole cents, tax included. `lines` is a list of (unit_price_in_dollars, quantity)."""
    subtotal = 0.0
    for unit_price, quantity in lines:
        subtotal += unit_price * quantity
    tax = subtotal * tax_percent / 100
    return int((subtotal + tax) * 100)
